import type { ActionFunctionArgs } from "react-router";
import { authenticate } from "../shopify.server";
import db from "../db.server";

export const action = async ({ request }: ActionFunctionArgs) => {
  const { shop, session, topic } = await authenticate.webhook(request);

  console.log(`Received ${topic} webhook for ${shop}`);

  // Webhook requests can trigger multiple times and after an app has already been uninstalled.
  // If this webhook already ran, the session may have been deleted previously.
  if (session) {
    await db.session.deleteMany({ where: { shop } });
  }

  return new Response();
};

import type { HeadersFunction, LoaderFunctionArgs } from "react-router";
import { useLoaderData, useNavigate } from "react-router";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";
import { getShopSubscription } from "../billing.server";
import { PLAN_LIMITS } from "../plans";
import db from "../db.server";
import {
  Page,
  Layout,
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
  Divider,
  Box,
} from "@shopify/polaris";

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const [subscription, zipCount] = await Promise.all([
    getShopSubscription(shop),
    db.zipCode.count({ where: { shop } }),
  ]);

  return { subscription, zipCount, shop };
};

export default function SettingsPage() {
  const { subscription, zipCount, shop } = useLoaderData<typeof loader>();
  const navigate = useNavigate();
  const limits = PLAN_LIMITS[subscription.planTier];

  return (
    <Page
      title="Settings"
      subtitle="Manage your app settings and subscription"
      backAction={{ onAction: () => navigate("/app") }}
    >
      <Layout>
        {/* Subscription Info */}
        <Layout.Section>
          <Card>
            <BlockStack gap="400">
              <Text as="h2" variant="headingMd">
                Subscription
              </Text>
              <Divider />
              <InlineStack align="space-between" blockAlign="center">
                <BlockStack gap="100">
                  <Text as="p" variant="bodyMd">
                    Current Plan
                  </Text>
                  <InlineStack gap="200" blockAlign="center">
                    <Badge
                      tone={
                        subscription.planTier === "ultimate"
                          ? "attention"
                          : subscription.planTier === "pro"
                            ? "info"
                            : "enabled"
                      }
                    >
                      {subscription.planTier === "ultimate"
                        ? "Ultimate"
                        : subscription.planTier === "pro"
                          ? "Pro"
                          : "Free"}
                    </Badge>
                    {subscription.planTier === "free" && (
                      <Text as="span" tone="subdued" variant="bodySm">
                        Limited features
                      </Text>
                    )}
                  </InlineStack>
                </BlockStack>
                <Button
                  variant="primary"
                  onClick={() => navigate("/app/pricing")}
                >
                  {subscription.planTier === "free"
                    ? "Upgrade Plan"
                    : "Manage Plan"}
                </Button>
              </InlineStack>
            </BlockStack>
          </Card>
        </Layout.Section>

        {/* Usage */}
        <Layout.Section>
          <Card>
            <BlockStack gap="400">
              <Text as="h2" variant="headingMd">
                Usage
              </Text>
              <Divider />
              <InlineStack align="space-between">
                <Text as="p">Zip Codes Used</Text>
                <Text as="p" fontWeight="semibold">
                  {zipCount}
                  {limits.maxZipCodes !== Infinity
                    ? ` / ${limits.maxZipCodes}`
                    : " (Unlimited)"}
                </Text>
              </InlineStack>
              <InlineStack align="space-between">
                <Text as="p">Blocked Zip Codes</Text>
                <Text as="p" fontWeight="semibold">
                  {limits.allowBlocked ? "Enabled" : "Not Available"}
                </Text>
              </InlineStack>
              <InlineStack align="space-between">
                <Text as="p">Store</Text>
                <Text as="p" fontWeight="semibold">
                  {shop}
                </Text>
              </InlineStack>
            </BlockStack>
          </Card>
        </Layout.Section>

        {/* General Settings */}
        <Layout.Section>
          <Card>
            <BlockStack gap="400">
              <Text as="h2" variant="headingMd">
                General Settings
              </Text>
              <Divider />
              <Box padding="200">
                <Text as="p" tone="subdued">
                  More settings options are coming soon, including default
                  messages, notification preferences, and API access
                  configuration.
                </Text>
              </Box>
            </BlockStack>
          </Card>
        </Layout.Section>
      </Layout>
    </Page>
  );
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

