   471→  function wireWidget(wid, cfg, API_BASE, SHOP) {
   472→    var inp = document.getElementById(wid + "-inp");
   473→    var btn = document.getElementById(wid + "-btn");
   474→    var res = document.getElementById(wid + "-res");
   475→    if (!inp || !btn || !res) return;
   476→
   477→    function normalizeZip(raw) {
   478→      var z = raw.trim().toUpperCase();
   479→      z = z.replace(/\s+/g, '');        // collapse all spaces (UK: SW1A 2AA → SW1A2AA)
   480→      z = z.replace(/-\d{4}$/, '');     // strip US ZIP+4 suffix (90210-1234 → 90210)
   481→      return z;
   482→    }
   483→
   484→    function setBtnLoading(loading) {
   485→      var iconEl = btn.querySelector('.zcc-btn-icon');
   486→      var labelEl = btn.querySelector('.zcc-btn-label');
   487→      btn.disabled = loading;
   488→      if (loading) {
   489→        if (iconEl) iconEl.innerHTML = ICONS.spinner;
   490→        if (labelEl) labelEl.textContent = '\u2026';
   491→      } else {
   492→        if (iconEl) iconEl.innerHTML = ICONS.search;
   493→        if (labelEl) labelEl.textContent = cfg.buttonText;
   494→      }
   495→    }
   496→
   497→    function checkZip() {
   498→      var zip = normalizeZip(inp.value);
   499→      inp.value = zip;  // Update the input field to show the normalized value (clean UX)
   500→      if (!zip) { inp.focus(); return; }
   501→
   502→      setBtnLoading(true);
   503→      res.innerHTML = "";
   504→
   505→      fetch(
   506→        API_BASE + "/api/zip-check?shop=" + encodeURIComponent(SHOP) +
   507→          "&zip=" + encodeURIComponent(zip)
   508→      )
   509→        .then(function (r) {
   510→          if (!r.ok) {
   511→            // Non-2xx: try to parse JSON error body, fall back to status text
   512→            return r.json().catch(function() {
   513→              return { error: 'Server error (' + r.status + ')' };
   514→            });
   515→          }
   516→          return r.json();
   517→        })
   518→        .then(function (data) {
   519→          setBtnLoading(false);
   520→
   521→          // If the API returned an error object (no allowed field), treat as a
   522→          // transient server error and show it in the result area rather than
   523→          // falling through with undefined message text.
   524→          if (data.error && data.allowed === undefined) {
   525→            res.innerHTML = '<div class="zcc-result fail"><div class="zcc-result-icon">' + ICONS.xCircle + '</div><div class="zcc-result-content"><div class="zcc-result-message">Something went wrong. Please try again.</div></div></div>';
   526→            try {
   527→              sessionStorage.removeItem('zcc:valid');
   528→              sessionStorage.removeItem('zcc:zip');
   529→              window.dispatchEvent(new CustomEvent('zcc:validated', { detail: { valid: false, zip: zip } }));
   530→            } catch(e) {}
   531→            return;
   532→          }
   533→
   534→          // Store validation result for cart page
   535→          try {
   536→            sessionStorage.setItem('zcc:valid', data.allowed ? 'true' : 'false');
   537→            sessionStorage.setItem('zcc:zip', zip);
   538→            sessionStorage.setItem('zcc:shop', SHOP);
   539→            // Fire custom event for other scripts to listen to
   540→            window.dispatchEvent(new CustomEvent('zcc:validated', {
   541→              detail: { valid: data.allowed, zip: zip }
   542→            }));
   543→          } catch(e) { /* sessionStorage may be unavailable */ }
   544→
   545→          if (data.allowed) {
   546→            var html = '<div class="zcc-result ok">' +
   547→              '<div class="zcc-result-icon">' + ICONS.check + '</div>' +
   548→              '<div class="zcc-result-content">' +
   549→              '<div class="zcc-result-message">' + esc(data.message) + '</div>';
   550→            if (cfg.showEta && data.eta) {
   551→              html += '<div class="zcc-meta">' + ICONS.truck + '<span>Estimated delivery: <strong>' + esc(data.eta) + '</strong></span></div>';
   552→            }
   553→            if (cfg.showZone && data.zone) {
   554→              html += '<div class="zcc-meta">' + ICONS.location + '<span>Zone: <strong>' + esc(data.zone) + '</strong></span></div>';
   555→            }
   556→            if (cfg.showDeliveryDays && data.daysOfWeek) {
   557→              var days = data.daysOfWeek.split(',').map(function(d) { return d.trim(); }).join(' \u00b7 ');
   558→              html += '<div class="zcc-meta zcc-days">' + ICONS.calendar + '<span>' + esc(days) + '</span></div>';
   559→            }
   560→            if (cfg.showCutoffTime && data.cutoffTime) {
   561→              var parts = data.cutoffTime.split(':');
   562→              var hr = parseInt(parts[0], 10);
   563→              var min = parts[1] || '00';
   564→              var ampm = hr >= 12 ? 'PM' : 'AM';
   565→              var hr12 = hr % 12 || 12;
   566→              html += '<div class="zcc-meta zcc-cutoff">' + ICONS.clock + '<span>Order by <strong>' + hr12 + ':' + min + ' ' + ampm + '</strong> for same-day</span></div>';
   567→            }
   568→            if (data.codAvailable === true) {
   569→              html += '<div class="zcc-cod zcc-cod--available">' + ICONS.card + ' Cash on Delivery Available</div>';
   570→            } else if (data.codAvailable === false) {
   571→              html += '<div class="zcc-cod zcc-cod--unavailable">' + ICONS.card + ' COD Not Available</div>';
   572→            }
   573→            if (data.returnPolicy) {
