   575→            }
   576→            html += '</div></div>';
   577→            res.innerHTML = html;
   578→          } else {
   579→            var html = '<div class="zcc-result fail">' +
   580→              '<div class="zcc-result-icon">' + ICONS.xCircle + '</div>' +
   581→              '<div class="zcc-result-content">' +
   582→              '<div class="zcc-result-message">' + esc(data.message) + '</div>';
   583→            if (cfg.showWaitlistOnFailure) {
   584→              html +=
   585→                '<div class="zcc-wl">' +
   586→                '<button class="zcc-wl-toggle" id="' + wid + '-wl-toggle" type="button">' +
   587→                ICONS.mail +
   588→                ' Request delivery to your area</button>' +
   589→                '<div id="' + wid + '-wl-form" style="display:none;margin-top:12px">' +
