   598→
   599→            if (cfg.showWaitlistOnFailure) {
   600→              // Wire "Request ZIP Code" toggle link
   601→              var wlToggle = document.getElementById(wid + "-wl-toggle");
   602→              var wlForm = document.getElementById(wid + "-wl-form");
