   922→// ── Reusable position tile selector ─────────────────────────────────────────
   923→const PositionTile = memo(function PositionTile({
   924→  value,
   925→  label,
   926→  selected,
   927→  disabled,
   928→  onSelect,
   929→  children,
   930→}: {
   931→  value: string;
   932→  label: string;
   933→  selected: boolean;
   934→  disabled: boolean;
   935→  onSelect: (v: string) => void;
   936→  children: React.ReactNode;
   937→}) {
   938→  const handleClick = useCallback(() => {
   939→    if (!disabled) onSelect(value);
   940→  }, [disabled, onSelect, value]);
   941→
   942→  return (
   943→    <button
   944→      type="button"
   945→      aria-pressed={selected}
   946→      onClick={handleClick}
   947→      disabled={disabled}
   948→      onKeyDown={(e) => {
   949→        if ((e.key === "Enter" || e.key === " ") && !disabled) {
   950→          e.preventDefault();
   951→          onSelect(value);
   952→        }
   953→      }}
   954→      style={{
   955→        flex: 1,
   956→        minWidth: 100,
   957→        appearance: "none",
   958→        WebkitAppearance: "none",
   959→        border: "none",
   960→        borderRadius: "var(--p-border-radius-200)",
   961→        padding: "var(--p-space-300)",
   962→        cursor: disabled ? "not-allowed" : "pointer",
   963→        opacity: disabled ? 0.5 : 1,
   964→        textAlign: "center",
   965→        outline: "none",
   966→        transition: "box-shadow 0.15s ease, background 0.15s ease",
   967→        background: selected
   968→          ? "var(--p-color-bg-surface-selected)"
   969→          : "var(--p-color-bg-surface)",
   970→        boxShadow: selected
   971→          ? "0 0 0 2px var(--p-color-border-emphasis)"
   972→          : "0 0 0 1px var(--p-color-border)",
   973→        fontFamily: "inherit",
   974→        color: "inherit",
   975→        fontSize: "inherit",
   976→      }}
   977→    >
   978→      <BlockStack gap="100" inlineAlign="center">
   979→        {children}
   980→        <Text as="p" variant="bodySm" fontWeight={selected ? "semibold" : "regular"}>
   981→          {label}
   982→        </Text>
   983→      </BlockStack>
   984→    </button>
   985→  );
   986→});
