   471→  function wireWidget(wid, cfg, API_BASE, SHOP) {
   472→    var inp = document.getElementById(wid + "-inp");
   473→    var btn = document.getElementById(wid + "-btn");
   474→    var res = document.getElementById(wid + "-res");
   475→    if (!inp || !btn || !res) return;
   476→
   477→    function normalizeZip(raw) {
   478→      var z = raw.trim().toUpperCase();
   479→      z = z.replace(/\s+/g, '');        // collapse all spaces (UK: SW1A 2AA → SW1A2AA)
   480→      z = z.replace(/-\d{4}$/, '');     // strip US ZIP+4 suffix (90210-1234 → 90210)
   481→      return z;
   482→    }
   483→
   484→    function setBtnLoading(loading) {
   485→      var iconEl = btn.querySelector('.zcc-btn-icon');
   486→      var labelEl = btn.querySelector('.zcc-btn-label');
   487→      btn.disabled = loading;
   488→      if (loading) {
   489→        if (iconEl) iconEl.innerHTML = ICONS.spinner;
   490→        if (labelEl) labelEl.textContent = '\u2026';
   491→      } else {
   492→        if (iconEl) iconEl.innerHTML = ICONS.search;
   493→        if (labelEl) labelEl.textContent = cfg.buttonText;
   494→      }
   495→    }
   496→
   497→    function checkZip() {
   498→      var zip = normalizeZip(inp.value);
   499→      inp.value = zip;  // Update the input field to show the normalized value (clean UX)
   500→      if (!zip) { inp.focus(); return; }
   501→
   502→      setBtnLoading(true);
   503→      res.innerHTML = "";
   504→
   505→      fetch(
   506→        API_BASE + "/api/zip-check?shop=" + encodeURIComponent(SHOP) +
   507→          "&zip=" + encodeURIComponent(zip)
   508→      )
   509→        .then(function (r) {
   510→          if (!r.ok) {
   511→            // Non-2xx: try to parse JSON error body, fall back to status text
   512→            return r.json().catch(function() {
   513→              return { error: 'Server error (' + r.status + ')' };
   514→            });
   515→          }
   516→          return r.json();
   517→        })
   518→        .then(function (data) {
   519→          setBtnLoading(false);
   520→
   521→          // If the API returned an error object (no allowed field), treat as a
   522→          // transient server error and show it in the result area rather than
   523→          // falling through with undefined message text.
   524→          if (data.error && data.allowed === undefined) {
   525→            console.error('[ZipCodeChecker] API returned error:', data.error, '| API_BASE="' + API_BASE + '" SHOP="' + SHOP + '"');
   526→            res.innerHTML = '<div class="zcc-result fail"><div class="zcc-result-icon">' + ICONS.xCircle + '</div><div class="zcc-result-content"><div class="zcc-result-message">Something went wrong. Please try again.</div></div></div>';
   527→            try {
   528→              sessionStorage.removeItem('zcc:valid');
   529→              sessionStorage.removeItem('zcc:zip');
   530→              window.dispatchEvent(new CustomEvent('zcc:validated', { detail: { valid: false, zip: zip } }));
   531→            } catch(e) {}
   532→            return;
   533→          }
   534→
   535→          // Store validation result for cart page
   536→          try {
   537→            sessionStorage.setItem('zcc:valid', data.allowed ? 'true' : 'false');
   538→            sessionStorage.setItem('zcc:zip', zip);
   539→            sessionStorage.setItem('zcc:shop', SHOP);
   540→            // Fire custom event for other scripts to listen to
   541→            window.dispatchEvent(new CustomEvent('zcc:validated', {
   542→              detail: { valid: data.allowed, zip: zip }
   543→            }));
   544→          } catch(e) { /* sessionStorage may be unavailable */ }
   545→
   546→          if (data.allowed) {
   547→            var html = '<div class="zcc-result ok">' +
   548→              '<div class="zcc-result-icon">' + ICONS.check + '</div>' +
   549→              '<div class="zcc-result-content">' +
   550→              '<div class="zcc-result-message">' + esc(data.message) + '</div>';
   551→            if (cfg.showEta && data.eta) {
   552→              html += '<div class="zcc-meta">' + ICONS.truck + '<span>Estimated delivery: <strong>' + esc(data.eta) + '</strong></span></div>';
   553→            }
   554→            if (cfg.showZone && data.zone) {
   555→              html += '<div class="zcc-meta">' + ICONS.location + '<span>Zone: <strong>' + esc(data.zone) + '</strong></span></div>';
   556→            }
   557→            if (cfg.showDeliveryDays && data.daysOfWeek) {
   558→              var days = data.daysOfWeek.split(',').map(function(d) { return d.trim(); }).join(' \u00b7 ');
   559→              html += '<div class="zcc-meta zcc-days">' + ICONS.calendar + '<span>' + esc(days) + '</span></div>';
   560→            }
   561→            if (cfg.showCutoffTime && data.cutoffTime) {
   562→              var parts = data.cutoffTime.split(':');
   563→              var hr = parseInt(parts[0], 10);
   564→              var min = parts[1] || '00';
   565→              var ampm = hr >= 12 ? 'PM' : 'AM';
   566→              var hr12 = hr % 12 || 12;
   567→              html += '<div class="zcc-meta zcc-cutoff">' + ICONS.clock + '<span>Order by <strong>' + hr12 + ':' + min + ' ' + ampm + '</strong> for same-day</span></div>';
   568→            }
   569→            if (data.codAvailable === true) {
   570→              html += '<div class="zcc-cod zcc-cod--available">' + ICONS.card + ' Cash on Delivery Available</div>';
   571→            } else if (data.codAvailable === false) {
   572→              html += '<div class="zcc-cod zcc-cod--unavailable">' + ICONS.card + ' COD Not Available</div>';
   573→            }
   574→            if (data.returnPolicy) {
   575→              html += '<div class="zcc-return-policy">' + ICONS.refresh + '<span>' + esc(data.returnPolicy) + '</span></div>';
   576→            }
   577→            html += '</div></div>';
   578→            res.innerHTML = html;
   579→          } else {
   580→            var html = '<div class="zcc-result fail">' +
   581→              '<div class="zcc-result-icon">' + ICONS.xCircle + '</div>' +
   582→              '<div class="zcc-result-content">' +
   583→              '<div class="zcc-result-message">' + esc(data.message) + '</div>';
   584→            if (cfg.showWaitlistOnFailure) {
   585→              html +=
   586→                '<div class="zcc-wl">' +
   587→                '<button class="zcc-wl-toggle" id="' + wid + '-wl-toggle" type="button">' +
   588→                ICONS.mail +
   589→                ' Request delivery to your area</button>' +
