 411→
 412→  // Handle notify results (zip, selected-zips, bulk-action-notify)
 413→  useEffect(() => {
 414→    if (
 415→      fetcher.data &&
 416→      "action" in fetcher.data &&
 417→      (fetcher.data.action === "notify-zip" || fetcher.data.action === "notify-selected-zips" || fetcher.data.action === "bulk-action-notify")
 418→    ) {
 419→      const data = fetcher.data as {
 420→        action: string;
 421→        zipCode?: string;
 422→        emails: string[];
 423→        count: number;
 424→        emailsSent?: number;
