 432→          emails: data.emails,
 433→          count: data.count,
 434→          emailsSent: data.emailsSent,
 435→        });
 436→      }
 437→      setNotifyResultModalOpen(true);
 438→      setSelectedZips(new Set());
 439→    }
 440→  }, [fetcher.data]);
 441→
 442→  const filteredEntries = useMemo(() => {
