 523→        } else if (fetcherAction === "rejected") {
 524→          shopify.toast.show("Request rejected");
 525→        } else if (fetcherAction === "deleted-notified") {
 526→          shopify.toast.show("Notified entries cleared");
 527→        } else if (fetcherAction === "bulk-accepted") {
 528→          const count = "count" in fetcher.data ? fetcher.data.count : 0;
 529→          shopify.toast.show(`${count} entries accepted`);
 530→        } else if (fetcherAction === "bulk-rejected") {
 531→          const count = "count" in fetcher.data ? fetcher.data.count : 0;
 532→          shopify.toast.show(`${count} entries rejected`);
 533→        } else if (fetcherAction === "bulk-deleted") {
 534→          const count = "count" in fetcher.data ? fetcher.data.count : 0;
 535→          shopify.toast.show(`${count} entries deleted`);
 536→        }
 537→      }
 538→    }
 539→  }, [fetcher.state, fetcher.data, shopify]);
 540→
 541→  const handleCopyEmails = useCallback(() => {
 542→    if (!notifyResult) return;
 543→    navigator.clipboard.writeText(notifyResult.emails.join(", ")).then(() => {
 544→      setCopySuccess(true);
 545→      setTimeout(() => setCopySuccess(false), 2000);
 546→    });
 547→  }, [notifyResult]);
 548→
 549→  const handleDeleteNotified = useCallback(() => {
 550→    const fd = new FormData();
 551→    fd.set("intent", "delete-all-notified");
 552→    fetcher.submit(fd, { method: "POST" });
 553→  }, [fetcher]);
 554→
 555→  const handleAccept = useCallback(
 556→    (id: string) => {
 557→      const fd = new FormData();
 558→      fd.set("intent", "accept");
 559→      fd.set("id", id);
 560→      fetcher.submit(fd, { method: "POST" });
 561→    },
 562→    [fetcher],
 563→  );
 564→
 565→  const handleReject = useCallback(
 566→    (id: string) => {
 567→      const fd = new FormData();
 568→      fd.set("intent", "reject");
 569→      fd.set("id", id);
 570→      fetcher.submit(fd, { method: "POST" });
 571→    },
 572→    [fetcher],
 573→  );
 574→
 575→  const handleNotifyZip = useCallback(
 576→    (zipCode: string) => {
 577→      const fd = new FormData();
 578→      fd.set("intent", "notify-zip");
 579→      fd.set("zipCode", zipCode);
 580→      fetcher.submit(fd, { method: "POST" });
 581→    },
 582→    [fetcher],
 583→  );
 584→
 585→  // ZIP checkbox handlers
 586→  const handleToggleZip = useCallback((zipCode: string) => {
 587→    setSelectedZips(prev => {
