 593→  }, []);
 594→
 595→  const handleSelectAllZips = useCallback((checked: boolean) => {
 596→    if (checked) {
 597→      setSelectedZips(new Set(zipWaitingCounts.map(z => z.zipCode)));
 598→    } else {
