 625→      } else if (selectionType === "page") {
 626→        setSelectedEntryIds(isSelecting ? paginatedEntries.map((e: WaitlistEntry) => e.id) : []);
 627→      } else if (typeof selection === "string") {
 628→        setSelectedEntryIds(prev =>
 629→          isSelecting ? [...prev, selection] : prev.filter(id => id !== selection)
 630→        );
 631→      }
 632→    },
 633→    [filteredEntries, paginatedEntries],
 634→  );
