 642→      fd.set("bulkType", bulkType);
 643→      fetcher.submit(fd, { method: "POST" });
 644→      setSelectedEntryIds([]);
 645→    },
 646→    [selectedEntryIds, fetcher],
 647→  );
 648→
 649→  if (isFreePlan) {
 650→    return (
 651→      <Page
 652→        title="Customer Waitlist"
 653→        subtitle="Customers waiting for delivery availability in their area"
