                </Text>
              </BlockStack>
            </Card>
          </Layout.Section>

          {/* ----------------------------------------------------------------
              Section 3: Notifications (NEW)
          ---------------------------------------------------------------- */}
          <Layout.Section>
            <Card>
              <BlockStack gap="400">
                <BlockStack gap="100">
                  <Text as="h2" variant="headingMd">
                    Waitlist Notifications
                  </Text>
                  <Text as="p" tone="subdued" variant="bodyMd">
                    Get notified by email when customers join the waitlist.
                  </Text>
                </BlockStack>
                <Divider />
                {notificationFetcher.data &&
