    {
      content: "Accept Selected",
      onAction: () => handleBulkAction("accept"),
    },
    {
      content: "Reject Selected",
      onAction: () => handleBulkAction("reject"),
    },
    {
      content: "Delete Selected",
      onAction: () => handleBulkAction("delete"),
      destructive: true,
    },
  ];

